layer.css:
[data-ryt="pitch"] { color: rgb(155, 155, 163); border-left: 5px solid rgb(74, 77, 86); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.85; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(155, 155, 163); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 16px; transition: background-color 0.075s ease-in, border-color 0.075s ease-in; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-top: 1px solid var(--ryt-border); border-radius: 0px; transition: background-color 0.075s ease-in, border-color 0.075s ease-in; border-right: none; border-bottom: none; border-left: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(74, 77, 86); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.075s ease-in, border-color 0.075s ease-in }
[data-ryt="hero"] h1 { color: rgb(234, 234, 234); font-family: var(--ryt-font-heading); font-size: 32px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: 0.48px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(234, 234, 234); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.075s ease-in, border-color 0.075s ease-in }
[data-ryt="section"] > h2 { color: rgb(234, 234, 234); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(234, 234, 234); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.075s ease-in, border-color 0.075s ease-in }
[data-ryt="header"] { border-bottom: 1px solid var(--ryt-border); border-top: none }
[data-ryt="nav"] a { color: rgb(234, 234, 234); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 2.25; letter-spacing: 0.24px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(234, 234, 234); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 4.8px; padding-right: 8px; padding-bottom: 4.8px; padding-left: 8px; transition: background-color 0.075s ease-in, border-color 0.075s ease-in }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.85; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.075s ease-in, border-color 0.075s ease-in }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: 0.1px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(74, 77, 86); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.15s ease-in }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(234, 234, 234); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.85; letter-spacing: 0.1px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(234, 234, 234); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.075s ease-in, border-color 0.075s ease-in }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; border-top-width: medium; border-right-width: medium; border-bottom-width: medium; border-left-width: medium; border-top-style: none; border-right-style: none; border-bottom-style: none; border-left-style: none; border-top-color: currentcolor; border-right-color: currentcolor; border-bottom-color: currentcolor; border-left-color: currentcolor; color: var(--ryt-accent); color: rgb(234, 234, 234) }
[data-ryt="nav"] a:hover { opacity: 1; color: var(--ryt-accent) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: rgb(82, 146, 255); color: var(--ryt-accent) }
